static void _memset_pattern16_impl(void *b, const void *pattern16, size_t len) {
  unsigned char *p = (unsigned char *)b;
  const unsigned char *pat = (const unsigned char *)pattern16;
  size_t i;
  for (i = 0; i < len; i++) p[i] = pat[i & 15];
}
